private void validateAndUpdateAttributeGroupStatus(GUPPricingAttributeLink _link)
{
    GUPPricingAttributeGroup attributeGroup = GUPPricingAttributeGroup::findByName(_link.PriceAttributeGroupName);
    if (attributeGroup.IsValid == NoYes::Yes && !attributeGroup.validateStructure())
    {
        ttsbegin;
        attributeGroup.IsValid = NoYes::No;
        attributeGroup.update();
        ttscommit;
    }
}

public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    if (_entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert || _entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Update)
    {
        if (_dataSourceCtx.name() == dataEntityDataSourceStr(GUPProductPricingAttributeLinkEntity, GUPPricingAttributeLink))
        {
            GUPPricingAttributeGroup attributeGroup = GUPPricingAttributeGroup::findByName(this.PricingAttributeGroup);
            if (!attributeGroup)
            {
                throw error("@GlobalUnifiedPricing:GUPPricingAttributeGroup_NotExsiting");
            }
            if (GUPPricingAttributeGroup::isPricingAttributeGroupUsed(attributeGroup.Name))
            {
                throw error("@GlobalUnifiedPricing:CombinationCannotBeUpdated");
            }
            if (attributeGroup.SourceLevel != GUPPricingAttributeSourceLevel::Line)
            {
                throw error(strFmt("@GlobalUnifiedPricing:GUPPricingAttributeGroup_IncorrectSourceLevel", attributeGroup.Name, "Header"));
            }
        }
    }
    super(_entityCtx, _dataSourceCtx);
}

public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret;
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(GUPProductPricingAttributeLinkEntity, GUPPricingAttributeLink))
    {
        GUPPricingAttributeLink link = _dataSourceCtx.getBuffer();
        GUPPricingAttributeGroup attributeGroup = GUPPricingAttributeGroup::findByName(this.PricingAttributeGroup);


        List                    attributes = GUPPricingAttributeRepository::getAllPricingAttributes();
        Enumerator              enum       = attributes.getEnumerator();
        GUPIPricingAttribute    pricingAttr;
        GUPPricingAttributeLink linkLocal;
        DictClass               dc;

        boolean validAttribute = false;
        while (enum.moveNext())
        {
            GUPPricingAttributeSourceLevel  sourceLevel;
            str                             fieldName;

            pricingAttr = enum.current();
            linkLocal   = GUPPricingAttributeRepository::toPriceAttributeLink(pricingAttr);

            if (this.AttributeName == linkLocal.AttributeName && this.SourceName == pricingAttr.getQueryBuilderDatasourceIdentifier())
            {
                validAttribute = true;
                sourceLevel = GUPPricingAttributeRepository::getPricingAttributeAttributeAsObject(
                pricingAttr,
                attributeStr(GUPPricingAttributeSourceDiscoveryAttribute)).parmLevel();

                if (sourceLevel != attributeGroup.SourceLevel)
                {
                    throw error(strFmt("@GlobalUnifiedPricing:GUPPricingAttributeGroupEntityCheckSourceLevel", attributeGroup.SourceLevel));
                }
                link.initFromPricingAttribute(pricingAttr);
                link.PriceAttributeClassId = linkLocal.PriceAttributeClassId;
                link.AttributeProviderClassId = linkLocal.AttributeProviderClassId;
                link.AttributeSourceType = GUPPricingAttributeSourceType::Table;
                break;
            }
        }
        if (!validAttribute)
        {
            throw error("Invalid Attribute");
        }
    }
    ret = super(_entityCtx, _dataSourceCtx);

    return ret;
}

public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret;

    ret = super(_entityCtx, _dataSourceCtx);
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(GUPProductPricingAttributeLinkEntity, GUPPricingAttributeLink))
    {
        GUPPricingAttributeLink link = _dataSourceCtx.getBuffer();
        this.validateAndUpdateAttributeGroupStatus(link);
    }
    return ret;
}
